// Получаем raw output от AI Agent1
const aiOutput = $json.output || $json.response_text || '';

// 1. Попробуем извлечь структуру по шаблонам (если AI вернул текст с ключами)
let status = 'unknown';
let taskId = $json.task_id || $json.sessionId || 'tmp-' + Date.now();
let message = aiOutput.trim().substring(0, 300);

// Извлекаем status по ключевым словам
if (aiOutput.toLowerCase().includes('completed') || aiOutput.toLowerCase().includes('успешно')) {
  status = 'completed';
} else if (aiOutput.toLowerCase().includes('running') || aiOutput.toLowerCase().includes('выполняется')) {
  status = 'running';
} else if (aiOutput.toLowerCase().includes('failed') || aiOutput.toLowerCase().includes('ошибка')) {
  status = 'failed';
} else if (aiOutput.toLowerCase().includes('queued') || aiOutput.toLowerCase().includes('в очереди')) {
  status = 'queued';
}

// Извлекаем task_id из строки (шаблон: "task_id: xxx" или "ID: xxx")
const taskIdMatch = aiOutput.match(/task[_-]?id\s*[:=]\s*["']?([a-zA-Z0-9-_]+)/i) ||
                   aiOutput.match(/ID\s*[:=]\s*["']?([a-zA-Z0-9-_]+)/i);
if (taskIdMatch && taskIdMatch[1]) {
  taskId = taskIdMatch[1];
}

// Формируем user-facing message
let finalMessage;
switch (status) {
  case 'completed':
    finalMessage = `✅ Задача "${taskId}" завершена успешно! Готов к следующей команде.`;
    break;
  case 'running':
    finalMessage = `🔄 Задача "${taskId}" выполняется. Текущая позиция: x=5.2, y=8.7.`;
    break;
  case 'queued':
    finalMessage = `⏳ Задача "${taskId}" поставлена в очередь.`;
    break;
  case 'failed':
    finalMessage = `❌ Задача "${taskId}" завершилась с ошибкой. Повторите команду.`;
    break;
  default:
    finalMessage = `ℹ️ Статус не определён. Ответ AI: "${message.replace(/"/g, '”').substring(0, 120)}..."`;
}

// Возвращаем строго валидный JSON
return [{
  json: {
    status: status,
    message: finalMessage,
    task_id: taskId
  }
}];

// Генерируем 5 итераций как объекты (для Loop Over Items)
return [
  { iteration: 1 },
  { iteration: 2 },
  { iteration: 3 },
  { iteration: 4 },
  { iteration: 5 }
];

// Получаем body из Webhook (входные данные)
const input = $json;

// Если пришёл объект с body — извлекаем команду из body.command
let cmd = '';
if (input.body && typeof input.body === 'object') {
  cmd = input.body.command || input.body.chatInput || '';
} else if (typeof input === 'string') {
  // Редкий случай: raw строка
  cmd = input;
} else {
  cmd = input.command || input.chatInput || '';
}

cmd = cmd.trim();

// Если команда пустая или шаблонная — даем fallback
if (!cmd || cmd === 'Выполните команду' || cmd === 'введите команду') {
  cmd = 'сканируй зону 1';
}

return [{
  json: {
    chatInput: cmd,
    sessionId: 'nanorobot-' + Date.now(),
    originalCommand: cmd
  }
}];

// AI Agent возвращает: { "output": "{...}" }
const rawJsonString = $json['output'];

let parsed;
try {
  parsed = JSON.parse(rawJsonString);
} catch (e) {
  // Fallback на случай ошибки
  parsed = {
    action: 'error',
    target: 'unknown',
    task_id: 'tmp-' + Date.now(),
    response_text: '❌ Ошибка: AI вернул некорректный JSON'
  };
}

return [{
  json: parsed
}];

// Убедимся, что передаём chatInput с сырыми данными статуса
const iteration = $json.iteration || 1;
const sessionId = $json.sessionId || 'tmp-' + Date.now();

// Предположим, что статус пришёл из HTTP Request1 или Code Node
const rawStatus = {
  status: "running",
  position: "x=5.2,y=8.7",
  action: "scan",
  target: "area_5",
  task_id: "tmp-12345"
};

return [{
  json: {
    iteration,
    sessionId,
    chatInput: JSON.stringify(rawStatus)  // ← это ключевое!
  }
}];
